SELECT SAFE_DIVIDE(SUM(ad_spend_attributed_rub), SUM(sales_revenue_seller_base_rub)) AS drr
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(returns_qty) AS returns_qty
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

WITH d AS (
  SELECT day FROM `wb_mart.V_DASH_KPI_DAILY`
  WHERE {{day}}
)
SELECT SUM(s.settlement_goods_rub) AS settlement_goods_rub
FROM d JOIN `wb_mart.V_DASH_SETTLEMENT_DAILY` s USING (day)

WITH f AS (
  SELECT day FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
  WHERE {{day}}
)
SELECT SUM(IF(e.after_product_cogs_eligible, e.product_cogs_rub, NULL)) AS product_cogs_rub
FROM f JOIN `wb_mart.V_DASH_EXECUTIVE_ECONOMICS_DAILY` e USING (day)

WITH f AS (
  SELECT day FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
  WHERE {{day}}
)
SELECT SUM(e.period_result_after_product_cogs_rub) AS period_result_after_cogs_rub
FROM f JOIN `wb_mart.V_DASH_EXECUTIVE_ECONOMICS_DAILY` e USING (day)

WITH d AS (
  SELECT day FROM `wb_mart.V_DASH_KPI_DAILY`
  WHERE {{day}}
)
SELECT SUM(s.post_realization_deductions_rub) AS post_realization_deductions_rub
FROM d JOIN `wb_mart.V_DASH_SETTLEMENT_DAILY` s USING (day)

WITH d AS (
  SELECT day FROM `wb_mart.V_DASH_KPI_DAILY`
  WHERE {{day}}
)
SELECT SUM(s.wb_payout_rub) AS wb_payout_rub
FROM d JOIN `wb_mart.V_DASH_SETTLEMENT_DAILY` s USING (day)

SELECT SUM(sales_revenue_buyer_paid_rub) AS buyer_paid_rub
FROM `wb_mart.V_DASH_KPI_DAILY`
WHERE {{day}}

SELECT SUM(ad_spend_billed_rub) AS ad_spend_billed_rub
FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
WHERE {{day}}

SELECT SUM(ad_spend_unallocated_rub) AS ad_spend_unallocated_rub
FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
WHERE {{day}}

SELECT SUM(exceptional_compensation_rub) AS exceptional_compensation_rub
FROM `wb_mart.V_DASH_FINANCE_CORRECTED_DAILY`
WHERE {{day}}
